using System.Net;
using System.Net.Sockets;
using System.Buffers.Binary;
using System.Text;
using System.Text.Json;
using Sezika.Tooling;

internal static class CorpusChecks
{
    internal static void Run(string root, Action<string, Action> check)
    {
        Budget Limit() => new(30, null, CancellationToken.None);
        static void Assert(bool condition, string message) { if (!condition) throw new InvalidOperationException(message); }
        static JsonElement Json(string value) { using var doc = JsonDocument.Parse(value); return doc.RootElement.Clone(); }
        static void Reject(Action operation) { try { operation(); } catch (Exception error) when (error is InvalidDataException or IOException or ArgumentException or JsonException or OperationCanceledException or TimeoutException or InvalidOperationException) { return; } throw new InvalidOperationException("Expected corpus rejection."); }
        string Folder(string name) => Path.Combine(root, "corpus-" + name);
        void SealQueue(string queue)
        { var questions = Path.Combine(queue, "questions.jsonl"); var reference = Path.Combine(queue, "reference-gold.jsonl"); CorpusJson.Write(Path.Combine(queue, "manifest.json"), new CorpusQueueManifest(new("QUESTION_QUEUE_READY_TEACHER_NOT_CALLED", queue, 1, 1, 0, 0, 0, false, false), CorpusJson.FileHash(questions, Limit()), CorpusJson.FileHash(reference, Limit()), new FileInfo(questions).Length, new FileInfo(reference).Length), CorpusJsonContext.Default.CorpusQueueManifest, Limit()); }
        CorpusPrepareRequest Fixture(string name, string source, string rows, string extension = ".jsonl")
        {
            var directory = Folder(name + "-source"); Directory.CreateDirectory(directory); var relative = "source/train" + extension; Directory.CreateDirectory(Path.Combine(directory, "source"));
            var path = Path.Combine(directory, relative); File.WriteAllText(path, rows, CorpusJson.Utf8);
            CorpusJson.Write(Path.Combine(directory, "ASSET_MANIFEST.json"), new[] { new CorpusAsset(source, relative, new FileInfo(path).Length, CorpusJson.FileHash(path, Limit()), "fixed-revision") }, CorpusJsonContext.Default.CorpusAssetArray, Limit());
            CorpusJson.Write(Path.Combine(directory, "RIGHTS_MANIFEST.json"), new[] { new CorpusRights(source, "eligible_under_declared_terms_with_attribution", "fixture-only") }, CorpusJsonContext.Default.CorpusRightsArray, Limit());
            return new(directory, Path.Combine(directory, "ASSET_MANIFEST.json"), Path.Combine(directory, "RIGHTS_MANIFEST.json"), Folder(name + "-output"), 20, 3, 2);
        }
        const string boolq = "{\"passage\":\"p\",\"question\":\"q\",\"answer\":false}";
        check("corpus BoolQ keeps false first", () => { var q = CorpusAdapters.Adapt("google/boolq", Json(boolq))[0]; Assert(q.Target.SequenceEqual(new[] { 1d, 0d }) && q.Candidates[0].Id == "false", "Boolean mapping changed."); });
        check("corpus invalid probability and missing SNLI label excluded", () => { Reject(() => CorpusAdapters.Question("s", "q", "Boolean", ["no", "yes"], [double.NaN, 1])); Reject(() => CorpusAdapters.Adapt("stanfordnlp/snli", Json("{\"premise\":\"p\",\"hypothesis\":\"h\",\"label\":-1}"))); });
        check("corpus HelpSteer keeps ordinal semantics", () => { var q = CorpusAdapters.Adapt("nvidia/HelpSteer2", Json("{\"prompt\":\"p\",\"response\":\"r\",\"helpfulness\":2,\"correctness\":2,\"coherence\":2,\"complexity\":2,\"verbosity\":2}")); Assert(q.Length == 5 && q[3].Instruction.Contains("not answer quality", StringComparison.Ordinal) && q[3].Target[2] == 1, "HelpSteer dimension confused."); });
        check("corpus typed Boolean reorder by identity", () => { var q = CorpusAdapters.Adapt("LocalLLaMA/typed-decisions", Json("{\"id\":\"x\",\"state\":\"s\",\"questions\":{\"q\":{\"type\":\"noul\",\"instructions\":\"q\",\"criteria\":{\"true\":\"yes\",\"false\":\"no\"}}},\"gold\":{\"q\":{\"probabilities\":{\"true\":0.8,\"false\":0.2}}}}"))[0]; Assert(q.Target.SequenceEqual(new[] { .2, .8 }) && q.Candidates[0].Text == "no", "Typed IDs reordered target."); });
        check("corpus original preference context mismatch rejected", () => Reject(() => CorpusAdapters.Adapt("Anthropic/hh-rlhf", Json("{\"chosen\":\"p\\n\\nAssistant: good\",\"rejected\":\"q\\n\\nAssistant: bad\"}"))));
        check("corpus science answer key identity", () => { var q = CorpusAdapters.Adapt("allenai/quartz", Json("{\"para\":\"fact\",\"para_id\":\"p\",\"id\":\"x\",\"question\":\"q\",\"choices\":{\"label\":[\"A\",\"B\"],\"text\":[\"first\",\"second\"]},\"answerKey\":\"B\"}"))[0]; Assert(q.Target[1] == 1, "Science key differs."); });
        check("corpus stockfish source reference retained", () => { var q = CorpusAdapters.Adapt("dwidlee/systemone-lite-phase2", Json("{\"state\":\"position\",\"instructions\":\"choose\",\"criteria_keys\":[\"a\",\"b\"],\"criteria_values\":[\"a\",\"b\"],\"label_alias\":\"b\",\"meta\":{\"task_schema\":\"staged_v1\",\"label_source\":\"stockfish\"}}"))[0]; Assert(q.LabelKind == "source_engine_reference" && q.LabelSemantics.Contains("not_teacher_accuracy", StringComparison.Ordinal), "Source reference promoted."); });
        check("corpus frozen ARC normalization sorts original labels correctly", () => { var q = CorpusAdapters.Adapt("allenai/ai2_arc", Json("{\"id\":\"x\",\"question\":\" A\\n B \",\"choices\":{\"label\":[\"2\",\"1\"],\"text\":[\"z\",\"a\"]},\"answerKey\":\"2\"}"))[0]; Assert(q.State == "A B" && q.Target.SequenceEqual(new[] { 0d, 1d }) && q.Candidates[0].Text == "a", "ARC frozen normalization differs."); });
        check("synthetic 24 Score pilot retains21 answers and3 abstentions", () =>
        { var rows = CorpusSyntheticTasks.Rows(0, true, 24, Limit()).ToArray(); var expected = new[] { 0, 0, 2, 1, 0, 1, 0, 3, 4, 0, 2, 4, 0, 0, 3, 0, 0, 4, 0, 1, 4 }; Assert(rows.Length == 24 && rows.Take(21).Select(r => Array.IndexOf(r.Reference.Target!, 1d)).SequenceEqual(expected) && rows.Skip(21).All(r => !r.Reference.Answerable && r.Reference.Target is null), "Frozen synthetic Score semantics changed."); });
        check("synthetic queue keeps bilingual family and private reference separate", () => { var rows = CorpusSyntheticTasks.Rows(1, false, 1000, Limit()).ToArray(); Assert(rows.Length == 472 && rows.GroupBy(r => r.Question.Family).All(g => g.Select(r => r.Question.Language).Distinct(StringComparer.Ordinal).Count() == 2) && rows.Any(r => !r.Reference.Answerable), "Synthetic family/abstention denominator differs."); var result = CorpusOperations.BuildQueue(new([], Folder("synthetic-queue"), 24, 1, 0, true), Limit()); Assert(result.Completed == 24 && !result.ActualTeacherCalled, "Pilot queue lost records."); });
        check("corpus NFC dedup conflict ledger and answer rotation", () =>
        {
            var path = Folder("writer"); Directory.CreateDirectory(path); using var writer = new CorpusWriter(path, 20, 2, 1, Limit()); var source = new CorpusProvenance("s", "r", "train.jsonl", new string('a', 64), "train", 1, "fixture", null);
            var q = CorpusAdapters.Question("e\u0301", "q", "Choice", ["gold", "wrong"], [1, 0], family: "f"); writer.Add(q, source, new string('b', 64)); writer.Add(q with { State = "é" }, source with { Row = 2 }, new string('c', 64)); writer.Add(q with { Target = [0, 1] }, source with { Row = 3 }, new string('d', 64)); writer.Add(q, source with { Row = 4 }, new string('e', 64)); writer.Close();
            Assert(writer.Records == 1 && writer.Duplicates == 1 && writer.Conflicts == 1 && writer.Quarantined == 2, "Dedup denominator differs."); var shard = writer.Shards(Limit())[0]; var row = CorpusJson.Lines(Path.Combine(path, shard.Path), 1, Limit()).Single(); var record = JsonSerializer.Deserialize(row, CorpusJsonContext.Default.CorpusRecord)!;
            Assert(record.Candidates[Array.IndexOf(record.Target, 1d)].Text == "gold" && File.ReadAllLines(Path.Combine(path, "exclusions.jsonl")).Length == 1, "Rotation answer or mandatory exclusion lost.");
        });
        check("corpus source SHA checked before decode", () => { var request = Fixture("bad-sha", "google/boolq", boolq + "\n"); File.AppendAllText(Path.Combine(request.DatasetRoot, "source/train.jsonl"), "tamper"); Reject(() => CorpusOperations.Prepare(request, Limit())); });
        check("corpus preparation closes SHA shards and complete denominator", () => { var request = Fixture("prepare", "google/boolq", boolq + "\n" + boolq + "\n"); var result = CorpusOperations.Prepare(request, Limit()); Assert(result.RecordsWritten == 1 && result.Duplicates == 1 && result.SourceCoverage[0].RowsRead == 2 && result.Shards.Sum(s => s.Records) == 1 && !result.FormalTrainingAdmitted, "Preparation report differs."); });
        check("corpus quoted CSV handles embedded newline", () => { var request = Fixture("csv", "google/boolq", "passage,question,answer\n\"first\nsecond\",q,false\n", ".csv"); var result = CorpusOperations.Prepare(request, Limit()); Assert(result.RecordsWritten == 1 && result.Quarantined == 0, "Quoted CSV row failed."); });
        check("corpus closed shards remain unchanged on resume", () =>
        {
            var request = Fixture("resume", "google/boolq", boolq + "\n{\"passage\":\"p2\",\"question\":\"q\",\"answer\":true}\n") with { MaximumRecords = 1 };
            Reject(() => CorpusOperations.Prepare(request, Limit())); var prior = CorpusJson.Read(Path.Combine(request.Output, "manifest.json"), CorpusJsonContext.Default.CorpusManifest, Limit()); var path = Path.Combine(request.Output, prior.Shards[0].Path); var original = File.ReadAllBytes(path);
            var result = CorpusOperations.Prepare(request with { MaximumRecords = 20, Resume = true }, Limit()); Assert(result.RecordsWritten == 2 && result.Stage == 2 && original.SequenceEqual(File.ReadAllBytes(path)) && File.Exists(Path.Combine(request.Output, "manifest-stage-0001.json")), "Resume overwrote closed bytes or lost stage.");
        });
        check("corpus logical byte rollover and task dedup cleanup", () =>
        {
            var path = Folder("byte-rollover"); Directory.CreateDirectory(path); using var writer = new CorpusWriter(path, 20, 20, 1, Limit(), maximumLogicalShardBytes: 2048); var source = new CorpusProvenance("s", "r", "train.jsonl", new string('a', 64), "train", 1, "fixture", null);
            for (var row = 0; row < 6; row++) writer.Add(CorpusAdapters.Question("state-" + row, "q", "Boolean", ["no", "yes"], [1, 0], family: "f"), source with { Row = row + 1 }, new string('b', 64)); writer.Close();
            var shards = writer.Shards(Limit()); Assert(shards.Length > 1 && shards.Sum(s => s.Records) == 6 && shards.All(s => s.Bytes <= 2112) && !File.Exists(Path.Combine(path, "dedup-stage-0001.bin")), "Logical rolling, physical cap or dedup cleanup failed.");
        });
        check("corpus partial multi-question row preserves physical and coverage denominators", () =>
        {
            var request = Fixture("multi-resume", "nvidia/HelpSteer2", "{\"prompt\":\"p\",\"response\":\"r\",\"helpfulness\":2,\"correctness\":2,\"coherence\":2,\"complexity\":2,\"verbosity\":2}\n") with { MaximumRecords = 2 };
            Reject(() => CorpusOperations.Prepare(request, Limit())); var prior = CorpusJson.Read(Path.Combine(request.Output, "manifest.json"), CorpusJsonContext.Default.CorpusManifest, Limit()); Assert(prior.RecordsWritten == 2 && prior.SourceCoverage[0].RecordsWritten == 2 && prior.SourceCoverage[0].RowsRead == 1 && prior.SourceCoverage[0].RowsFullyProcessed == 0, "Partial raw row written denominator lost.");
            var result = CorpusOperations.Prepare(request with { MaximumRecords = 20, Resume = true }, Limit()); Assert(result.RecordsWritten == 5 && result.SourceCoverage[0].RecordsWritten == 5 && result.SourceCoverage[0].RowsFullyProcessed == 1 && result.Shards.Sum(s => s.Records) == 5, "Resumed row skipped remaining questions or double-counted physical records.");
        });
        check("corpus cancelled request creates no output", () => { var request = Fixture("cancel", "google/boolq", boolq + "\n"); using var cancelled = new CancellationTokenSource(); cancelled.Cancel(); Reject(() => CorpusOperations.Prepare(request, new Budget(30, null, cancelled.Token))); Assert(!Directory.Exists(request.Output), "Cancel created output."); });
        check("corpus composition removes duplicates without modifying components", () =>
        { var first = Fixture("compose-a", "google/boolq", boolq + "\n"); var second = Fixture("compose-b", "google/boolq", boolq + "\n"); CorpusOperations.Prepare(first, Limit()); CorpusOperations.Prepare(second, Limit()); var hash = CorpusJson.FileHash(Path.Combine(first.Output, "manifest.json"), Limit()); var result = CorpusOperations.Compose(new([new(first.Output, hash), new(second.Output, CorpusJson.FileHash(Path.Combine(second.Output, "manifest.json"), Limit()))], Folder("compose"), 20, 2), Limit()); Assert(result.RecordsWritten == 1 && result.Duplicates == 1 && hash == CorpusJson.FileHash(Path.Combine(first.Output, "manifest.json"), Limit()), "Compose identity/count differs."); });
        check("corpus legacy frozen metadata import preserves original manifest bytes", () =>
        {
            var source = Fixture("legacy", "google/boolq", boolq + "\n"); var prepared = CorpusOperations.Prepare(source, Limit()); var legacy = Folder("legacy-frozen"); Directory.CreateDirectory(legacy);
            foreach (var name in new[] { "source-assets.json", "source-rights.json", "exclusions.jsonl" }) File.Copy(Path.Combine(source.Output, name), Path.Combine(legacy, name));
            foreach (var shard in prepared.Shards) { var destination = Path.Combine(legacy, shard.Path); Directory.CreateDirectory(Path.GetDirectoryName(destination)!); File.Copy(Path.Combine(source.Output, shard.Path), destination); }
            var path = Path.Combine(legacy, "manifest.json"); using (var memory = new FileStream(path, FileMode.CreateNew)) { using var writer = new Utf8JsonWriter(memory); writer.WriteStartObject(); writer.WriteNumber("schema_version", 1); writer.WriteString("status", "COMPLETE_PREPARATION_ONLY"); writer.WriteBoolean("pilot", false); writer.WriteBoolean("formal_training_admitted", false); writer.WriteNumber("records_written", prepared.RecordsWritten); writer.WritePropertyName("shards"); JsonSerializer.Serialize(writer, prepared.Shards, CorpusJsonContext.Default.CorpusShardArray); writer.WriteEndObject(); }
            var hash = CorpusJson.FileHash(path, Limit()); var binding = new CorpusBinding(hash, CorpusJson.FileHash(Path.Combine(legacy, "exclusions.jsonl"), Limit()), CorpusJson.FileHash(Path.Combine(legacy, "source-rights.json"), Limit()), CorpusJson.FileHash(Path.Combine(legacy, "source-assets.json"), Limit()), "source-assets.json", source.DatasetRoot); CorpusJson.Write(Path.Combine(legacy, "corpus-bindings.json"), binding, CorpusJsonContext.Default.CorpusBinding, Limit());
            var result = CorpusOperations.Compose(new([new(legacy, hash)], Folder("legacy-composed"), 20, 2), Limit()); Assert(result.RecordsWritten == 1 && hash == CorpusJson.FileHash(path, Limit()) && hash == CorpusJson.FileHash(Path.Combine(result.SourceCoverage.Length > 0 ? Folder("legacy-composed") : "bad", "components/root-00/manifest.json"), Limit()), "Legacy import changed original frozen bytes.");
        });
        foreach (var split in new[] { "train", "development", "test", "calibration", "ood", "OOD" })
        {
            var caseSplit = split;
            check("teacher split admission " + split, () =>
            { var question = new CorpusQueueRecord("r", new string('a', 64), caseSplit, "s", "q", "Boolean", [new("false", "no"), new("true", "yes")], "en", new("fixture", "r", "p", new string('b', 64), "train", 1, "fixture", null), new string('c', 64)); var request = new CorpusTeacherRequest("", "", "http://localhost/", "fixture", "fixture", "r", "fixture", new string('d', 64)); var result = CorpusOperations.Annotate(question, new("r", true, [0, 1], "supplied fact"), new("r", true, [0, 1]), request, new string('e', 64), new string('f', 64)); Assert(result.TrainingAdmission == (caseSplit == "train" ? "experimental_candidate" : CorpusOperations.AnnotationUse(caseSplit)) && !result.FormalTrainingAdmitted, "Reference split promoted."); });
        }
        check("teacher unknown split fails before HTTP", () => Reject(() => CorpusOperations.AnnotationUse("unknown")));
        check("teacher abstention requires null probability", () =>
        { var question = new CorpusQueueRecord("r", new string('a', 64), "train", "s", "q", "Boolean", [new("false", "no"), new("true", "yes")], "en", new("fixture", "r", "p", new string('b', 64), "train", 1, "fixture", null), new string('c', 64)); var request = new CorpusTeacherRequest("", "", "http://localhost/", "fixture", "fixture", "r", "fixture", new string('d', 64)); Reject(() => CorpusOperations.Annotate(question, new("r", false, [0, 1], "x"), new("r", true, [0, 1]), request, "q", "r")); var result = CorpusOperations.Annotate(question, new("r", false, null, "uncertain"), new("r", true, [0, 1]), request, "q", "r"); Assert(result.TrainingAdmission == "excluded_abstention_or_reference_disagreement", "Abstention admitted."); });
        check("teacher HTTP protocol, exact request visibility, ledger and resume", () => TeacherFixture("http-success", false));
        check("teacher malformed response remains failed without fake annotation", () => TeacherFixture("http-failure", true));
        check("teacher unknown POST is preserved and never automatically repeated", () =>
        {
            var queue = Folder("unknown-queue"); Directory.CreateDirectory(queue); var question = new CorpusQueueRecord("unknown", new string('a', 64), "train", "s", "q", "Boolean", [new("false", "no"), new("true", "yes")], "en", new("fixture", "r", "p", new string('b', 64), "train", 1, "fixture", null), new string('c', 64));
            using (var w = CorpusJson.Writer(Path.Combine(queue, "questions.jsonl"))) CorpusJson.Line(w, question, CorpusJsonContext.Default.CorpusQueueRecord); using (var w = CorpusJson.Writer(Path.Combine(queue, "reference-gold.jsonl"))) CorpusJson.Line(w, new CorpusReference("unknown", true, [0, 1]), CorpusJsonContext.Default.CorpusReference); SealQueue(queue);
            var calls = 0; using var client = new HttpClient(new FixtureHandler(_ => { calls++; throw new HttpRequestException("fixture disconnected after POST"); })); var config = new CorpusTeacherRequest(queue, Folder("unknown-output"), "http://127.0.0.1:12345/v1/responses", "fixture", "fixture", "r", "fixture", new string('d', 64), 1, 1, 5);
            var first = CorpusOperations.Collect(config, Limit(), client); var resumed = CorpusOperations.Collect(config with { Resume = true }, Limit(), client); Assert(calls == 1 && first.Failed == 1 && resumed.Failed == 1 && File.ReadAllText(Path.Combine(config.Output, "ledger.jsonl")).Contains("unknown", StringComparison.Ordinal), "Unknown POST was retried or falsely accepted.");
        });
        check("teacher real local HTTP socket protocol", () =>
        {
            var queue = Folder("socket-queue"); Directory.CreateDirectory(queue); var question = new CorpusQueueRecord("socket", new string('a', 64), "train", "s", "q", "Boolean", [new("false", "no"), new("true", "yes")], "en", new("fixture", "r", "p", new string('b', 64), "train", 1, "fixture", null), new string('c', 64));
            using (var w = CorpusJson.Writer(Path.Combine(queue, "questions.jsonl"))) CorpusJson.Line(w, question, CorpusJsonContext.Default.CorpusQueueRecord); using (var w = CorpusJson.Writer(Path.Combine(queue, "reference-gold.jsonl"))) CorpusJson.Line(w, new CorpusReference("socket", true, [0, 1]), CorpusJsonContext.Default.CorpusReference); SealQueue(queue);
            using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(10)); using var listener = new TcpListener(IPAddress.Loopback, 0); listener.Start(1); var port = ((IPEndPoint)listener.LocalEndpoint).Port;
            var server = Task.Run(async () =>
            {
                using var peer = await listener.AcceptTcpClientAsync(deadline.Token); using var stream = peer.GetStream(); using var reader = new StreamReader(stream, Encoding.ASCII, false, 1024, true); var length = 0; var first = await reader.ReadLineAsync(deadline.Token); Assert(first == "POST /v1/responses HTTP/1.1", "Local request line differs.");
                for (var i = 0; i < 64; i++) { var header = await reader.ReadLineAsync(deadline.Token); if (string.IsNullOrEmpty(header)) break; Assert(header.Length <= 8192, "Local header bound."); if (header.StartsWith("Content-Length:", StringComparison.OrdinalIgnoreCase)) length = int.Parse(header[15..].Trim(), System.Globalization.CultureInfo.InvariantCulture); if (i == 63) throw new InvalidDataException("Local header count bound."); }
                Assert(length is >= 1 and <= 65_536, "Local request body bound."); var body = new char[length]; await reader.ReadBlockAsync(body.AsMemory(), deadline.Token); using var json = JsonDocument.Parse(new string(body)); Assert(json.RootElement.GetProperty("model").GetString() == "fixture", "Local model identity differs.");
                var label = JsonSerializer.Serialize(new CorpusTeacherLabel("socket", true, [0, 1], "local fixture"), CorpusJsonContext.Default.CorpusTeacherLabel); var response = Encoding.UTF8.GetBytes("{\"output_text\":" + JsonSerializer.Serialize(label, CorpusJsonContext.Default.String) + "}");
                var headers = Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: " + response.Length + "\r\nConnection: close\r\n\r\n"); await stream.WriteAsync(headers, deadline.Token); await stream.WriteAsync(response, deadline.Token); await stream.FlushAsync(deadline.Token);
            }, deadline.Token);
            try { var result = CorpusOperations.Collect(new(queue, Folder("socket-output"), $"http://127.0.0.1:{port}/v1/responses", "fixture", "fixture", "r", "fixture", new string('d', 64), 1, 1, 5), Limit()); Assert(result.Completed == 1 && !result.ActualTeacherCalled && result.SyntheticTransport && result.HttpRequestsIssued == 1, "Local socket annotation scope/count failed."); server.WaitAsync(TimeSpan.FromSeconds(10)).GetAwaiter().GetResult(); }
            finally { deadline.Cancel(); listener.Stop(); try { server.WaitAsync(TimeSpan.FromSeconds(2)).GetAwaiter().GetResult(); } catch (OperationCanceledException) { } }
        });
        void TeacherFixture(string name, bool malformed)
        {
            var queue = Folder(name + "-queue"); Directory.CreateDirectory(queue); var question = new CorpusQueueRecord("r", new string('a', 64), "train", "s", "q", "Boolean", [new("false", "no"), new("true", "yes")], "en", new("fixture", "r", "p", new string('b', 64), "train", 1, "fixture", null), new string('c', 64));
            using (var writer = CorpusJson.Writer(Path.Combine(queue, "questions.jsonl"))) CorpusJson.Line(writer, question, CorpusJsonContext.Default.CorpusQueueRecord); using (var writer = CorpusJson.Writer(Path.Combine(queue, "reference-gold.jsonl"))) CorpusJson.Line(writer, new CorpusReference("r", true, [0, 1]), CorpusJsonContext.Default.CorpusReference); SealQueue(queue);
            var calls = 0; using var client = new HttpClient(new FixtureHandler(message =>
            {
                calls++; var bytes = message.Content!.ReadAsByteArrayAsync().GetAwaiter().GetResult(); using var requestJson = JsonDocument.Parse(bytes); var text = requestJson.RootElement.GetProperty("input")[1].GetProperty("content").GetString()!;
                Assert(!text.Contains("Target", StringComparison.Ordinal) && !text.Contains("Source", StringComparison.Ordinal), "Private target/provenance leaked to teacher.");
                var label = malformed ? "{}" : JsonSerializer.Serialize(new CorpusTeacherLabel("r", true, [0, 1], "fact"), CorpusJsonContext.Default.CorpusTeacherLabel);
                return new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent("{\"output_text\":" + JsonSerializer.Serialize(label, CorpusJsonContext.Default.String) + "}", Encoding.UTF8, "application/json") };
            }));
            var config = new CorpusTeacherRequest(queue, Folder(name + "-output"), "http://127.0.0.1:12345/v1/responses", "fixture", "fixture", "r", "fixture", new string('d', 64), 1, 1, 5);
            var result = CorpusOperations.Collect(config, Limit(), client); Assert(calls == 1 && result.Completed == (malformed ? 0 : 1) && result.Failed == (malformed ? 1 : 0) && !result.ActualTeacherCalled && result.SyntheticTransport && result.HttpRequestsIssued == 1 && File.Exists(Path.Combine(config.Output, "ledger.jsonl")), "Teacher denominator/ledger/scope differs.");
            var resumed = CorpusOperations.Collect(config with { Resume = true }, Limit(), client); Assert(calls == 1 && resumed.Completed == (malformed ? 0 : 1), "Resume repeated HTTP or lost outcome.");
            if (!malformed) { var annotation = Path.Combine(config.Output, "items", CorpusJson.Sha("r"), "annotation.json"); File.Delete(annotation); var recovered = CorpusOperations.Collect(config with { Resume = true }, Limit(), client); Assert(calls == 1 && recovered.Completed == 1 && File.Exists(annotation), "Raw response recovery repeated POST or lost annotation."); }
            if (!malformed) { var reviewRoot = Folder(name + "-review"); var report = CorpusOperations.BuildDataset(new(config.Output, reviewRoot, "review", CorpusJson.FileHash(Path.Combine(config.Output, "report.json"), Limit()), CorpusJson.FileHash(Path.Combine(config.Output, "teacher-records.jsonl"), Limit()), 1), Limit()); Assert(report.Completed == 1 && File.Exists(Path.Combine(reviewRoot, "source-evidence/items", CorpusJson.Sha("r"), "response.json")) && File.ReadAllText(Path.Combine(reviewRoot, "review-template.jsonl")).Contains("pending", StringComparison.Ordinal), "Corpus teacher review failed to preserve raw evidence/pending semantics."); }
        }
        check("dataset prompt build preserves original decision bytes", () =>
        {
            var source = Folder("dataset-source"); Directory.CreateDirectory(Path.Combine(source, "requests")); var request = "{\"schema_version\":1,\"model_id\":\"student\",\"state\":\"s\",\"questions\":[{\"id\":\"q\",\"type\":\"boolean\",\"instruction\":\"q\"}]}"; var bytes = CorpusJson.Utf8.GetBytes(request); File.WriteAllBytes(Path.Combine(source, "requests/r.json"), bytes); File.WriteAllText(Path.Combine(source, "manifest.json"), "{}", CorpusJson.Utf8); File.WriteAllText(Path.Combine(source, "candidates.jsonl"), "{\"record_id\":\"r\",\"request_path\":\"requests/r.json\",\"request_sha256\":\"" + CorpusJson.Sha(bytes) + "\",\"prompt_path\":\"prompts/r.txt\"}\n", CorpusJson.Utf8);
            var output = Folder("dataset-output"); CorpusOperations.BuildDataset(new(source, output, "prompt-v2", CorpusJson.FileHash(Path.Combine(source, "manifest.json"), Limit()), CorpusJson.FileHash(Path.Combine(source, "candidates.jsonl"), Limit()), 1), Limit()); Assert(File.ReadAllBytes(Path.Combine(output, "requests/r.json")).SequenceEqual(bytes) && File.ReadAllText(Path.Combine(output, "prompts/r.txt")).Contains(request, StringComparison.Ordinal), "Prompt lost exact request.");
        });
        check("research frozen metadata plan retains evaluation split and SHA", () =>
        {
            var source = Folder("research-source"); Directory.CreateDirectory(Path.Combine(source, "metadata/hf")); File.WriteAllText(Path.Combine(source, "seeds.json"), "[{\"id\":\"owner/data\"},{\"id\":\"owner/missing\"}]", CorpusJson.Utf8); File.WriteAllText(Path.Combine(source, "metadata/hf/owner--data.json"), "{\"id\":\"owner/data\",\"sha\":\"1234567\",\"cardData\":{\"license\":\"fixture\"},\"siblings\":[{\"rfilename\":\"test.jsonl\",\"size\":4},{\"rfilename\":\"README.md\",\"size\":3},{\"rfilename\":\"predictions/results.json\",\"size\":2}]}", CorpusJson.Utf8);
            var output = Folder("research-output"); var report = CorpusOperations.BuildResearchPlan(new(Path.Combine(source, "seeds.json"), source, output, 2, 3), Limit()); var plan = CorpusJson.Read(Path.Combine(output, "raw-download-plan.json"), CorpusJsonContext.Default.CorpusResearchAssetArray, Limit()); Assert(report.Failed == 1 && plan.Length == 2 && plan.Single(p => p.Path.EndsWith("test.jsonl", StringComparison.Ordinal)).Split == "source-test-evaluation", "Research metadata absence or split lost.");
        });
        check("research completeness keeps pending partials and physical row denominator", () =>
        {
            var source = Folder("complete-source"); Directory.CreateDirectory(Path.Combine(source, "raw")); var data = CorpusJson.Utf8.GetBytes("{}\n{}\n"); File.WriteAllBytes(Path.Combine(source, "raw/train.jsonl"), data); File.WriteAllBytes(Path.Combine(source, "raw/test.jsonl.range-partial"), [1, 2]);
            File.WriteAllText(Path.Combine(source, "plan.json"), "[{\"dataset\":\"owner/data\",\"path\":\"raw/train.jsonl\",\"url\":\"https://example.invalid/train\",\"split\":\"source-train\",\"revision\":\"fixed\",\"expected_bytes\":6,\"expected_sha256\":\"" + CorpusJson.Sha(data) + "\"},{\"dataset\":\"owner/data\",\"path\":\"raw/test.jsonl\",\"url\":\"https://example.invalid/test\",\"split\":\"source-test-evaluation\",\"expected_bytes\":4}]", CorpusJson.Utf8);
            File.WriteAllText(Path.Combine(source, "ledger.jsonl"), "{\"url\":\"https://example.invalid/train\",\"status\":\"downloaded\",\"bytes\":6,\"sha256\":\"" + CorpusJson.Sha(data) + "\"}\n{\"url\":\"https://example.invalid/test\",\"status\":\"failed\",\"error\":\"fixture\"}\n", CorpusJson.Utf8);
            var report = CorpusOperations.CheckResearch(new(source, [Path.Combine(source, "plan.json")], [Path.Combine(source, "ledger.jsonl")], Folder("complete-report.json"), 2, 2), Limit()); Assert(report.DownloadedFiles == 1 && report.MissingFiles == 1 && report.PhysicalRows == 2 && report.Missing[0].PartialBytes == 2 && !report.RowsAreUniqueQuestions && !report.AllSelectedFilesDownloaded, "Completeness or physical count changed meaning.");
        });
        check("research Parquet footer read preserves count and rejects encrypted format", () =>
        {
            var path = Folder("footer.parquet"); var metadata = new byte[] { 0x36, 84, 0 }; var length = new byte[4]; BinaryPrimitives.WriteInt32LittleEndian(length, metadata.Length); File.WriteAllBytes(path, [.. "PAR1"u8, .. metadata, .. length, .. "PAR1"u8]);
            Assert(CorpusParquetFooter.ReadRows(path, Limit()) == 42, "Parquet physical rows differ."); var invalid = Folder("encrypted.parquet"); File.WriteAllBytes(invalid, [.. "PAR1"u8, .. metadata, .. length, .. "PARE"u8]); Reject(() => CorpusParquetFooter.ReadRows(invalid, Limit()));
        });
        check("independent seed positive outcome mapping and disagreement retained", () =>
        {
            var source = Folder("seeds-source"); Directory.CreateDirectory(source); var binary = Path.Combine(source, "binary.jsonl"); var parallel = Path.Combine(source, "parallel.jsonl"); var manifest = Path.Combine(source, "manifest.json"); File.WriteAllText(binary, "{\"instance_id\":\"one\",\"outcomes\":[\"B\",\"A\"],\"gold_distribution\":{\"B\":0.4,\"A\":0.6}}\n", CorpusJson.Utf8); File.WriteAllText(parallel, "{\"instance_id\":\"two\",\"gold_distribution\":{\"True\":0.4,\"False\":0.6},\"generator_metadata\":{\"parallel_primitives\":{\"source_instance_id\":\"one\"}},\"queries\":{\"choice\":{},\"noul\":{},\"score\":{}}}\n", CorpusJson.Utf8); File.WriteAllText(manifest, "{\"evaluation\":[{\"data_files\":[\"eval.jsonl\"]}]}", CorpusJson.Utf8); File.WriteAllText(Path.Combine(source, "eval.jsonl"), "{}\n", CorpusJson.Utf8);
            var request = new CorpusSeedCheckRequest(binary, CorpusJson.FileHash(binary, Limit()), parallel, CorpusJson.FileHash(parallel, Limit()), manifest, CorpusJson.FileHash(manifest, Limit()), source, Folder("seeds-report.json"), 1); var result = CorpusOperations.CheckSeeds(request, Limit()); Assert(result.Status == "PASS_SEED_CONTRACT_ONLY" && result.MatchedPairs == 1 && !result.GoldConstructionRecomputed && !result.ModelCalibrationValidated, "First outcome mapping or evidence scope changed.");
            File.WriteAllText(parallel, File.ReadAllText(parallel).Replace("\"True\":0.4,\"False\":0.6", "\"True\":0.6,\"False\":0.4", StringComparison.Ordinal), CorpusJson.Utf8); var changed = CorpusOperations.CheckSeeds(request with { ParallelSha256 = CorpusJson.FileHash(parallel, Limit()), Output = Folder("seeds-failed.json") }, Limit()); Assert(changed.Status == "FAIL_SEED_CONTRACT" && changed.CrossPrimitiveConsistencyErrors == 1, "Reference discrepancy disappeared.");
        });
        check("corpus budget arithmetic uses frozen historical timings without live claims", () =>
        {
            var directory = Folder("estimate-source"); Directory.CreateDirectory(directory); var plan = Path.Combine(directory, "plan.json"); var profile = Path.Combine(directory, "profile.json"); var training = Path.Combine(directory, "training.json");
            File.WriteAllText(plan, "{\"RunId\":\"fixture\",\"ExpectedGpuUuid\":\"fixture-gpu\",\"MaximumUpdates\":5,\"CheckpointEvery\":2}", CorpusJson.Utf8); var planHash = CorpusJson.FileHash(plan, Limit());
            File.WriteAllText(profile, "{\"Status\":\"PASS_real_base_profile_only\",\"RunId\":\"fixture\",\"GpuUuid\":\"fixture-gpu\",\"MaximumStepSeconds\":3,\"Inputs\":{\"PlanSha256\":\"" + planHash + "\"}}", CorpusJson.Utf8);
            File.WriteAllText(training, "{\"Status\":\"PASS_experimental_GPU_updates_saved_only\",\"RunId\":\"fixture\",\"GpuUuid\":\"fixture-gpu\",\"CompletedUpdates\":5,\"InitialUpdates\":1,\"ElapsedSeconds\":10,\"Inputs\":{\"PlanSha256\":\"" + planHash + "\"}}", CorpusJson.Utf8);
            var result = CorpusOperations.Estimate(new(training, CorpusJson.FileHash(training, Limit()), profile, CorpusJson.FileHash(profile, Limit()), plan, planHash, [10], Folder("estimate.json")), Limit()); Assert(result.HistoricalUpdates == 4 && result.HistoricalSecondsPerUpdate == 2.5 && result.Scenarios[0].HistoricalConservativeFormulaSeconds == 1440 && !result.CurrentThroughputVerified && !result.GpuTrainingRun && !result.RentalAuthorizedOrPurchased, "Historical arithmetic denominator or live claims changed.");
        });
    }
    private sealed class FixtureHandler(Func<HttpRequestMessage, HttpResponseMessage> handler) : HttpMessageHandler
    {
        protected override HttpResponseMessage Send(HttpRequestMessage request, CancellationToken cancellationToken) { cancellationToken.ThrowIfCancellationRequested(); return handler(request); }
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken) => Task.FromResult(Send(request, cancellationToken));
    }
}
